import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Dhf_H6O0.js";const g=JSON.parse('{"title":"License Management","description":"","frontmatter":{},"headers":[],"relativePath":"settings/license.md","filePath":"settings/license.md"}'),o={name:"settings/license.md"};function r(s,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="license-management" tabindex="-1">License Management <a class="header-anchor" href="#license-management" aria-label="Permalink to &quot;License Management&quot;">​</a></h1><p>Your MindBehind license key is entered during first launch and managed in Settings.</p><h2 id="viewing-your-license-status" tabindex="-1">Viewing your license status <a class="header-anchor" href="#viewing-your-license-status" aria-label="Permalink to &quot;Viewing your license status&quot;">​</a></h2><p>Go to <strong>Settings</strong>. The <strong>License key</strong> section shows:</p><ul><li><strong>Status</strong> — <code>Active</code>, <code>Invalid</code>, or <code>No license key</code></li><li><strong>Stored key ends with</strong> — the last few characters of your key for reference</li></ul><h2 id="updating-your-key" tabindex="-1">Updating your key <a class="header-anchor" href="#updating-your-key" aria-label="Permalink to &quot;Updating your key&quot;">​</a></h2><ol><li>Paste a new key into the <strong>New license key</strong> field.</li><li>Click <strong>Save &amp; validate</strong>.</li><li>The app validates the key online and updates the status.</li></ol><h2 id="re-checking" tabindex="-1">Re-checking <a class="header-anchor" href="#re-checking" aria-label="Permalink to &quot;Re-checking&quot;">​</a></h2><p>If the validation server was temporarily unreachable, click <strong>Re-check now</strong> to retry validation with the stored key.</p><h2 id="removing-your-key" tabindex="-1">Removing your key <a class="header-anchor" href="#removing-your-key" aria-label="Permalink to &quot;Removing your key&quot;">​</a></h2><p>Click <strong>Remove stored key</strong> to clear the license from this device. The app returns to the activation overlay and the gateway stops.</p><h2 id="how-validation-works" tabindex="-1">How validation works <a class="header-anchor" href="#how-validation-works" aria-label="Permalink to &quot;How validation works&quot;">​</a></h2><ul><li>The key is validated <strong>online</strong> when you activate it.</li><li>While the app is running, it <strong>re-validates every 5 minutes</strong>.</li><li>If the server is temporarily unreachable, the last known state is used.</li><li>If the key becomes invalid (expired, revoked, or activated on another device), the <strong>gateway stops</strong> and the activation overlay reappears.</li><li>An internet connection is required for the initial activation and periodic re-validation.</li></ul><div class="info custom-block"><p class="custom-block-title">Privacy</p><p>Only your license key and a device identifier are sent to the MindBehind validation server. No usage data, server configurations, or document contents are transmitted.</p></div>',14)])])}const y=t(o,[["render",r]]);export{g as __pageData,y as default};
